  Future<void> _connectWithFacebook() async {
    final app = AppScope.of(context);
    final messenger = ScaffoldMessenger.of(context);
    final start = await app.startFacebookChatbotOAuth();
    if (!mounted) return;
    final url = start?.authorizationUrl.trim() ?? '';
    if (url.isEmpty) {
      messenger.showSnackBar(
        SnackBar(
          content: TfText(
            app.facebookChatbotError ??
                app.lastError ??
                app.strings.facebookLoginFailed,
          ),
        ),
      );
      return;
    }
    final uri = Uri.tryParse(url);
    if (uri == null) {
      messenger.showSnackBar(
        SnackBar(content: TfText(app.strings.facebookLoginFailed)),
      );
      return;
    }
    var opened = false;
    try {
      opened =
          await _browserChannel.invokeMethod<bool>('openUrl', {
            'url': uri.toString(),
          }) ??
          false;
    } catch (_) {
      opened = false;
    }
    if (!mounted) return;
    if (!opened) {
      messenger.showSnackBar(
        SnackBar(content: TfText(app.strings.facebookLoginFailed)),
      );
      return;
    }
    final oauthPages = await Navigator.of(context)
        .push<FacebookChatbotOAuthPages>(
          MaterialPageRoute<FacebookChatbotOAuthPages>(
            builder: (_) => const _FacebookOAuthBrowserWaitPage(),
            fullscreenDialog: true,
          ),
        );
    if (!mounted) return;
    var connected = false;
    final selectedSessionId = oauthPages?.sessionId.trim() ?? '';
    if (selectedSessionId.isNotEmpty) {
      if ((oauthPages?.pages.length ?? 0) == 1) {
        connected = await app.completeFacebookChatbotOAuth(
          sessionId: selectedSessionId,
          pageId: oauthPages!.pages.first.pageId,
        );
      } else {
        connected =
            await Navigator.of(context).push<bool>(
