class PhoneVerifyResult {
  PhoneVerifyResult({
    required this.status,
    this.login,
    this.signupToken,
    this.phone,
    this.inviteId,
    this.restaurantName,
    this.outletName,
  });

  final String status;
  final AdminLoginResult? login;
  final String? signupToken;
