    await addNotification(
      type: PosNotificationType.printFailed,
      title: strings.printFailed,
      body: reason,
      actionTarget: 'settings_printer',
      playSound: true,
    );
  }

  Future<void> _notifyPrinterUnavailableForCreatedOrder(
    OrderModel order,
  ) async {
