      _FacebookOAuthBrowserWaitPageState();
}

class _FacebookOAuthBrowserWaitPageState
    extends State<_FacebookOAuthBrowserWaitPage>
    with WidgetsBindingObserver {
  Timer? _pollTimer;
  bool _polling = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _pollTimer = Timer.periodic(const Duration(seconds: 2), (_) => _poll());
    WidgetsBinding.instance.addPostFrameCallback((_) => _poll());
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _pollTimer?.cancel();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      unawaited(_poll());
    }
  }

  Future<void> _poll() async {
    if (_polling || !mounted) return;
    _polling = true;
    setState(() => _error = null);
    try {
      final pages = await AppScope.of(
        context,
      ).loadLatestFacebookChatbotOAuthPages();
      if (!mounted) return;
      if (pages != null && pages.sessionId.trim().isNotEmpty) {
        Navigator.pop(context, pages);
      }
    } catch (error) {
      if (mounted) setState(() => _error = '$error');
    } finally {
      _polling = false;
    }
  }

  @override
  Widget build(BuildContext context) {
    final app = AppScope.of(context);
    return AppScaffold(
      title: app.strings.facebookLoginTitle,
      showDatePill: false,
      showBackButton: true,
      pinHeader: true,
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: TfCard(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              TfText(
                tfPick(
                  context,
                  en: 'Complete Facebook in your browser',
                  bn: 'ব্রাউজারে Facebook কানেক্ট শেষ করুন',
                ),
                style: Theme.of(
                  context,
                ).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w700),
              ),
              const SizedBox(height: 8),
              TfText(
                tfPick(
                  context,
                  en: 'After approving the Facebook Page, return to this app. We will finish the connection automatically.',
                  bn: 'Facebook Page অনুমোদন করার পর এই অ্যাপে ফিরে আসুন। কানেকশন অটোমেটিক শেষ হবে।',
                ),
                style: Theme.of(
                  context,
                ).textTheme.bodyMedium?.copyWith(color: PosColors.muted),
              ),
              const SizedBox(height: 18),
              Row(
                children: [
                  const SizedBox(
                    width: 18,
                    height: 18,
                    child: CircularProgressIndicator(strokeWidth: 2),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: TfText(
                      tfPick(
                        context,
                        en: 'Waiting for browser login...',
                        bn: 'ব্রাউজার লগইনের জন্য অপেক্ষা করছে...',
                      ),
                      style: Theme.of(
                        context,
                      ).textTheme.bodySmall?.copyWith(color: PosColors.textSec),
                    ),
                  ),
                ],
              ),
              if (_error != null && _error!.isNotEmpty) ...[
                const SizedBox(height: 10),
                TfText(
                  _error!,
                  style: Theme.of(
                    context,
                  ).textTheme.bodySmall?.copyWith(color: PosColors.danger),
                ),
              ],
              const SizedBox(height: 18),
              TfButton(
                label: tfPick(context, en: 'I am back', bn: 'আমি ফিরে এসেছি'),
                icon: Icons.refresh_rounded,
                busy: _polling,
                onPressed: _polling ? null : () => unawaited(_poll()),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _FacebookOAuthWebViewPage extends StatefulWidget {
  const _FacebookOAuthWebViewPage({required this.initialUrl});

  final String initialUrl;

  @override
  State<_FacebookOAuthWebViewPage> createState() =>
      _FacebookOAuthWebViewPageState();
}

class _FacebookOAuthWebViewPageState extends State<_FacebookOAuthWebViewPage> {
  WebViewController? _controller;
  String? _error;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _start());
  }

  Future<void> _start() async {
    final initialUri = Uri.tryParse(widget.initialUrl);
    if (initialUri == null) {
      setState(() => _error = 'Facebook Login URL is invalid.');
      return;
    }
    final controller = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..setUserAgent(_kFacebookOAuthUserAgent)
      ..setNavigationDelegate(
        NavigationDelegate(
          onNavigationRequest: (request) {
            final handled = _handleDoneUrl(request.url);
            return handled
                ? NavigationDecision.prevent
                : NavigationDecision.navigate;
          },
          onPageFinished: _handleDoneUrl,
          onWebResourceError: (error) {
            if (!mounted || error.isForMainFrame != true) return;
            setState(() {
              _error = 'Could not load Facebook Login (${error.description}).';
            });
          },
        ),
      );
    setState(() => _controller = controller);
    await controller.loadRequest(initialUri);
  }

  bool _handleDoneUrl(String rawUrl) {
    final uri = Uri.tryParse(rawUrl);
    if (uri == null || uri.path != '/admin/chatbot/facebook/oauth/done') {
      return false;
    }
    final success = uri.queryParameters['status'] == 'success';
    if (success) {
      final sessionId = uri.queryParameters['sessionId']?.trim() ?? '';
      if (sessionId.isNotEmpty && mounted) Navigator.pop(context, sessionId);
      return true;
    }
    if (mounted) {
      setState(() {
        _error =
            uri.queryParameters['message'] ??
            AppScope.of(context).strings.facebookLoginFailed;
      });
    }
    return false;
  }

  @override
  Widget build(BuildContext context) {
    final text = AppScope.of(context).strings;
    final error = _error;
    return AppScaffold(
      title: text.facebookLoginTitle,
      showDatePill: false,
      showBackButton: true,
      pinHeader: true,
      fillBody: true,
      child: Column(
        children: [
          if (error != null && error.isNotEmpty) ...[
            TfCard(
              color: PosColors.dangerSoft,
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Icon(
                    Icons.error_outline_rounded,
                    color: PosColors.danger,
                    size: 20,
                  ),
                  SizedBox(width: 8),
                  Expanded(
                    child: TfText(
                      error,
                      style: Theme.of(
                        context,
                      ).textTheme.bodySmall?.copyWith(color: PosColors.danger),
                    ),
                  ),
                ],
              ),
            ),
            SizedBox(height: 10),
          ],
          Expanded(
            child: ClipRRect(
              borderRadius: BorderRadius.circular(PosRadii.md),
              child: ColoredBox(
                color: PosColors.surface,
                child: _controller == null
                    ? TfLoading(message: text.facebookLoginTitle)
                    : WebViewWidget(controller: _controller!),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _FacebookPageSelectionPage extends StatefulWidget {
  const _FacebookPageSelectionPage({required this.sessionId});

  final String sessionId;

  @override
  State<_FacebookPageSelectionPage> createState() =>
      _FacebookPageSelectionPageState();
}

class _FacebookPageSelectionPageState
    extends State<_FacebookPageSelectionPage> {
  List<FacebookChatbotPage> _pages = const [];
  String _selectedPageId = '';
  String? _error;
  bool _loading = true;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _load());
  }

  Future<void> _load() async {
    final app = AppScope.of(context);
    final result = await app.loadFacebookChatbotOAuthPages(widget.sessionId);
    if (!mounted) return;
    final pages = result?.pages ?? const <FacebookChatbotPage>[];
    setState(() {
      _pages = pages;
      _selectedPageId = pages.length == 1 ? pages.first.pageId : '';
      _error = pages.isEmpty
          ? app.facebookChatbotError ?? app.strings.facebookLoginFailed
          : null;
      _loading = false;
    });
  }

  Future<void> _complete() async {
    final app = AppScope.of(context);
    final ok = await app.completeFacebookChatbotOAuth(
      sessionId: widget.sessionId,
      pageId: _selectedPageId,
    );
    if (!mounted) return;
    if (ok) {
      Navigator.pop(context, true);
      return;
    }
    setState(() {
      _error =
          app.facebookChatbotError ?? app.lastError ?? app.strings.saveFailed;
    });
  }

  @override
  Widget build(BuildContext context) {
    final app = AppScope.of(context);
    final text = app.strings;
    return AppScaffold(
      title: text.selectFacebookPage,
      showDatePill: false,
      showBackButton: true,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          TfText(text.selectFacebookPageSubtitle),
          SizedBox(height: 12),
          if (_loading)
            TfLoading(message: text.facebookLoginTitle)
          else
            RadioGroup<String>(
              groupValue: _selectedPageId,
              onChanged: (value) =>
                  setState(() => _selectedPageId = value ?? ''),
              child: Column(
                children: [
                  for (final page in _pages)
                    RadioListTile<String>(
                      value: page.pageId,
                      title: TfText(
                        page.pageName.isEmpty ? page.pageId : page.pageName,
                      ),
                      subtitle: page.pageName.isEmpty
                          ? null
                          : TfText(page.pageId),
                    ),
                ],
              ),
            ),
          if ((_error ?? '').isNotEmpty) ...[
            SizedBox(height: 8),
            TfText(
              _error!,
              style: Theme.of(
                context,
              ).textTheme.bodySmall?.copyWith(color: PosColors.danger),
            ),
          ],
          SizedBox(height: 12),
          TfButton(
            label: text.confirmFacebookPage,
            icon: Icons.check_rounded,
            busy: app.busy,
            fullWidth: true,
            onPressed: app.busy || _selectedPageId.isEmpty ? null : _complete,
          ),
        ],
      ),
    );
  }
}

