        SizedBox(
          width: 118,
          child: TfButton(
            label: widget.text.cancel,
            variant: TfButtonVariant.paper,
            fullWidth: true,
            onPressed: _submitting ? null : () => Navigator.pop(context, false),
          ),
        ),
        SizedBox(
          width: 150,
          child: TfButton(
            label: widget.text.wipeRestaurantConfirm,
            variant: TfButtonVariant.dark,
            fullWidth: true,
