class _FacebookOAuthBrowserWaitPageState
    extends State<_FacebookOAuthBrowserWaitPage>
    with WidgetsBindingObserver {
  Timer? _pollTimer;
  bool _polling = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _pollTimer = Timer.periodic(const Duration(seconds: 2), (_) => _poll());
    WidgetsBinding.instance.addPostFrameCallback((_) => _poll());
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _pollTimer?.cancel();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      unawaited(_poll());
    }
  }

  Future<void> _poll() async {
    if (_polling || !mounted) return;
    _polling = true;
    setState(() => _error = null);
    try {
      final pages = await AppScope.of(
        context,
      ).loadLatestFacebookChatbotOAuthPages();
      if (!mounted) return;
      if (pages != null && pages.sessionId.trim().isNotEmpty) {
        Navigator.pop(context, pages);
      }
    } catch (error) {
      if (mounted) setState(() => _error = '$error');
    } finally {
      _polling = false;
    }
  }

  @override
