      });
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(AppScope.of(context).strings.heroLogoUploaded)),
      );
    } on MenuImageException catch (e) {
      setState(() => _saving = false);
